import{_ as t}from"./chunks/settings-cal.pc.ko.BDoJOykj.js";import{_ as o,o as i,c as n,a5 as e}from"./chunks/framework.D47SInms.js";const u=JSON.parse('{"title":"4. ZMP 캘리브레이션","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/add-on/zmp-calibration.md","filePath":"ko/guides/add-on/zmp-calibration.md","lastUpdated":1791600043000}'),r={name:"ko/guides/add-on/zmp-calibration.md"};function l(s,a,d,c,g,p){return i(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="_4-zmp-캘리브레이션" tabindex="-1">4. ZMP 캘리브레이션 <a class="header-anchor" href="#_4-zmp-캘리브레이션" aria-label="Permalink to &quot;4. ZMP 캘리브레이션&quot;">​</a></h1><p><strong>목표:</strong> 추가 모듈로 바뀐 무게 조건에서 로봇이 균형을 유지하도록, 영모멘트점(ZMP)을 다시 보정합니다.</p><p><strong>사전 조건:</strong> 3단계 <a href="/RBQ/nightly/ko/guides/add-on/payload-setting.html">Payload 설정</a> 완료 — 질량과 무게중심이 로봇에 등록되어 있어야 합니다.</p><h2 id="zmp-캘리브레이션의-역할" tabindex="-1">ZMP 캘리브레이션의 역할 <a class="header-anchor" href="#zmp-캘리브레이션의-역할" aria-label="Permalink to &quot;ZMP 캘리브레이션의 역할&quot;">​</a></h2><p>ZMP(Zero Moment Point) 캘리브레이션은 로봇이 서 있는 동안 지면 반력의 중심을 정렬해, 보행 중 균형을 유지할 수 있게 합니다. Payload가 바뀌면 무게중심이 이동하므로 이 단계가 필요합니다.</p><h2 id="시작하기-전에" tabindex="-1">시작하기 전에 <a class="header-anchor" href="#시작하기-전에" aria-label="Permalink to &quot;시작하기 전에&quot;">​</a></h2><ul><li>로봇을 <strong>평탄하고 단단한 바닥</strong>에 놓으세요.</li><li>로봇에 <strong>물체나 사람이 닿지 않도록</strong> 주변을 정리하고, <strong>한 걸음 걸을 공간</strong>을 비워 두세요.</li><li>앱이 로봇에 연결되어 있고, <strong>로봇이 서 있어야 합니다</strong>(STAND). 앉은 상태에서는 시작할 수 없습니다.</li></ul><h2 id="절차" tabindex="-1">절차 <a class="header-anchor" href="#절차" aria-label="Permalink to &quot;절차&quot;">​</a></h2><ol><li>앱에서 <strong>정비 → 캘리브레이션</strong>을 엽니다.</li></ol><figure style="text-align:center;"><img src="'+t+'" alt="정비 → 캘리브레이션" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">1단계 — 정비 → 캘리브레이션</figcaption></figure><ol start="2"><li><strong>무게 중심 보정</strong> 절의 <code>무게 중심 오프셋 자동 보정</code>을 누릅니다. 실행할 수 없는 상태면 버튼이 잠기고 이유가 그 자리에 표시됩니다.</li><li>확인 창에서 실행을 확정합니다.</li><li>로봇이 <strong>한 걸음 걸어 다리를 정렬한 뒤</strong> 자동 보정에 들어갑니다 — <strong>최대 60초</strong>입니다.</li><li>완료되면 로봇이 <strong>스스로 값을 저장하고 STAND로 돌아옵니다.</strong></li><li>Stance → Walk로 전환해 추가 모듈을 단 상태에서도 정상적으로 보행하는지 확인합니다.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>보정 중에는 로봇에 물건을 올리거나 밀지 마세요. 실패해도 이전 보정값은 유지되며, 사유별 조치는 <a href="/RBQ/nightly/ko/manual/troubleshooting/calibration-tuning">캘리브레이션 &amp; 튜닝</a>에 정리되어 있습니다.</p></div></div><h2 id="완료" tabindex="-1">완료 <a class="header-anchor" href="#완료" aria-label="Permalink to &quot;완료&quot;">​</a></h2><p>추가 모듈 장착, Payload 등록, ZMP 캘리브레이션이 모두 완료되었습니다. 이제 평소대로 동작 명령을 보낼 수 있습니다 — 로봇 조작은 <strong><a href="/RBQ/nightly/ko/manual/gui/motion-commands.html">모션 명령</a></strong> 문서를 참고하세요.</p>',14)])])}const _=o(r,[["render",l]]);export{u as __pageData,_ as default};
